package solution
import "sort"
func AllocateFixed(t int,w []int)([]int,bool){if t<0||t>10000000||len(w)==0{return nil,false};s:=0;for _,x:=range w{if x<0||x>10000000{return nil,false};s+=x;if s>10000000{return nil,false}};if s==0{return nil,false};o:=make([]int,len(w));idx:=make([]int,len(w));used:=0;for i,x:=range w{o[i]=t*x/s;used+=o[i];idx[i]=i};sort.Slice(idx,func(i,j int)bool{a,b:=t*w[idx[i]]%s,t*w[idx[j]]%s;if a==b{return idx[i]<idx[j]};return a>b});for i:=0;i<t-used;i++{o[idx[i]]++};return o,true}
